# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe "Timekeeping write delay test hook" do
  # Anyone able to slow writes could degrade every company's entry writes, so
  # only the service identity may set a delay.
  it "refuses the write delay hook without the service token and leaves writes undelayed" do
    service_token = "service-#{SecureRandom.hex(24)}"
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => service_token
    ) do
      Timekeeping::TestHooks.clear_write_delay!
      user_token = mint_token({ sub: 7, company_id: 1, role: "owner" })
      body = JSON.generate("milliseconds" => 400)

      # The delay persists in a file, so it is checked after every refusal: a
      # refusal that set a delay could otherwise be hidden by a later one clearing it.
      [nil, "Bearer #{user_token}", "Bearer #{service_token}x"].each do |authorization|
        headers = { "Content-Type" => "application/json" }
        headers["Authorization"] = authorization if authorization
        post "/internal/v1/test-hooks/writes/delay", params: body, headers: headers

        expect([response.status, response.parsed_body]).to eq([401, { "reason" => "unauthorized" }])
        expect(Timekeeping::TestHooks.write_delay_seconds.to_f).to eq(0.0)
      end
    end
  ensure
    Timekeeping::TestHooks.clear_write_delay!
  end
end

RSpec.describe "Timekeeping write delay test hook" do
  it "refuses the write delay clear hook without the service token and keeps the delay set" do
    service_token = "service-#{SecureRandom.hex(24)}"
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => service_token
    ) do
      Timekeeping::TestHooks.delay_writes!(400)
      user_token = mint_token({ sub: 7, company_id: 1, role: "owner" })

      post "/internal/v1/test-hooks/writes/clear"
      expect([response.status, response.parsed_body]).to eq([401, { "reason" => "unauthorized" }])

      post "/internal/v1/test-hooks/writes/clear", headers: { "Authorization" => "Bearer #{user_token}" }
      expect([response.status, response.parsed_body]).to eq([401, { "reason" => "unauthorized" }])

      expect(Timekeeping::TestHooks.write_delay_seconds.to_f).to be > 0

      post "/internal/v1/test-hooks/writes/clear", headers: { "Authorization" => "Bearer #{service_token}" }
      expect(response.status).to eq(204)
      expect(Timekeeping::TestHooks.write_delay_seconds.to_f).to eq(0.0)
    end
  ensure
    Timekeeping::TestHooks.clear_write_delay!
  end
end

RSpec.describe "Timekeeping write delay test hook: measured write latency" do
  include_context "timekeeping entry writes"

  let(:company) { timekeeping_arrange.company }
  let(:project) { timekeeping_arrange.project(company:) }
  let(:owner) { timekeeping_arrange.user(company:, role: "owner") }
  let(:owner_token) { timekeeping_arrange.token_for(owner) }

  after { Timekeeping::TestHooks.clear_write_delay! }

  def write_delay_hook_post(path, body = nil)
    headers = { "Authorization" => "Bearer #{provider_service_token}" }
    headers["Content-Type"] = "application/json" if body
    post path, params: body && JSON.generate(body), headers: headers
    response.status
  end

  def write_delay_hook_entry_write
    post "/v1/companies/#{company}/entries",
         params: JSON.generate("project_id" => project, "work_date" => "2026-03-02", "duration" => 45.0,
                               "note" => "Review", "source" => "manual", "source_metadata" => {}),
         headers: { "Content-Type" => "application/json", "Authorization" => "Bearer #{owner_token}",
                    "Ownership-Generation" => timekeeping_arrange.current_generation.to_s,
                    "Idempotency-Key" => SecureRandom.uuid }
    expect(response.status).to eq(201)
  end

  # Latency bucket counts of the company's windows, as the metrics endpoint answers them.
  def write_delay_hook_buckets
    get "/internal/v1/metrics", headers: { "Authorization" => "Bearer #{provider_service_token}" }
    windows = response.parsed_body.fetch("companies").find { |entry| entry["company_id"] == company }.fetch("windows")
    windows.each_with_object(Hash.new(0)) do |window, sums|
      window.fetch("latency_ms_buckets").each { |bucket, count| sums[bucket] += count }
    end
  end

  def write_delay_hook_slow_count(buckets)
    buckets.sum { |bucket, count| bucket == "inf" || bucket.to_i > 300 ? count : 0 }
  end

  it "puts a write above the 300 ms bucket while a delay is set, and back at or under it once cleared" do
    expect(write_delay_hook_post("/internal/v1/test-hooks/writes/delay", { "milliseconds" => 400 })).to eq(204)
    write_delay_hook_entry_write
    expect(write_delay_hook_slow_count(write_delay_hook_buckets)).to eq(1)

    expect(write_delay_hook_post("/internal/v1/test-hooks/writes/clear")).to eq(204)
    expect(Timekeeping::TestHooks.write_delay_seconds).to eq(0.0)
    write_delay_hook_entry_write
    buckets = write_delay_hook_buckets
    expect([buckets.values.sum, write_delay_hook_slow_count(buckets)]).to eq([2, 1])
  end

  it "refuses a delay that is not a whole number of milliseconds within the limit and sets none" do
    [{ "milliseconds" => "400" }, { "milliseconds" => -1 }, { "milliseconds" => 5_001 }, {}].each do |body|
      expect(write_delay_hook_post("/internal/v1/test-hooks/writes/delay", body)).to eq(400)
      expect(response.parsed_body).to eq("reason" => "invalid_request")
    end
    expect(Timekeeping::TestHooks.write_delay_seconds).to eq(0.0)
  end

  it "keeps the delay in a file named for the Rails environment" do
    Timekeeping::TestHooks.delay_writes!(250)

    expect(File.basename(Timekeeping::TestHooks.write_delay_file)).to eq("write_delay_ms.#{Rails.env}")
    expect(File.read(Timekeeping::TestHooks.write_delay_file)).to eq("250")
    expect(Timekeeping::TestHooks.write_delay_seconds).to eq(0.25)
  end
end
